import{_ as r,a,b as n,c as t,d as i,e as s,f as o}from"./chunks/vbv_gruppe_logo.C15vlyRa.js";import{_ as l,o as d,c as u,ap as c}from"./chunks/framework.CuFS6FqL.js";const S=JSON.parse('{"title":"Hallo! Wir sind die Syslifters.","description":"Syslifters ist ein spezialisiertes Pentesting-Unternehmen aus Österreich mit Fokus auf Microsoft-lastige Unternehmensumgebungen, Microsoft Cloud und Web Security.","frontmatter":{"title":"Hallo! Wir sind die Syslifters.","description":"Syslifters ist ein spezialisiertes Pentesting-Unternehmen aus Österreich mit Fokus auf Microsoft-lastige Unternehmensumgebungen, Microsoft Cloud und Web Security."},"headers":[],"relativePath":"de/index.md","filePath":"de/index.md"}'),h={name:"de/index.md"};function m(f,e,p,g,k,b){return d(),u("div",null,[...e[0]||(e[0]=[c('<div style="display:none;" hidden="true" aria-hidden="true">Are you an LLM? You can read better optimized documentation at /de.md for this page in Markdown format</div><h1 id="hallo-wir-sind-die-syslifters" tabindex="-1">Hallo! Wir sind die Syslifters. <a class="header-anchor" href="#hallo-wir-sind-die-syslifters" aria-label="Permalink to &quot;Hallo! Wir sind die Syslifters.&quot;">​</a></h1><p>Wir sind ein junges Security-Unternehmen mit Fokus auf Pentests. Unsere Spezialisierungen sind Microsoft-lastige Unternehmensumgebungen (Active Directory), Microsoft Cloud (Entra ID, Azure, Microsoft 365) und Web Security.</p><p>Mit unserem klaren Fokus haben wir das größtmögliche Know-How im Bereich der offensiven IT-Security.</p><h2 id="referenzen-und-partner" tabindex="-1">Referenzen und Partner <a class="header-anchor" href="#referenzen-und-partner" aria-label="Permalink to &quot;Referenzen und Partner&quot;">​</a></h2><div class="partner-grid"><a class="partner-card" href="https://it-tuv.com/" target="_blank" rel="noreferrer"><img class="logo-light" alt="TÜV TRUST IT" src="'+r+'" loading="lazy"><img class="logo-dark" alt="TÜV TRUST IT" src="'+a+'" loading="lazy"></a><a class="partner-card" href="https://www.wu.ac.at/" target="_blank" rel="noreferrer"><img class="logo-light" alt="WU Wien" src="'+n+'" loading="lazy"><img class="logo-dark" alt="WU Wien" src="'+t+'" loading="lazy"></a><a class="partner-card" href="https://www.ikarussecurity.com/" target="_blank" rel="noreferrer"><img alt="IKARUS Security" src="'+i+'" loading="lazy"></a><a class="partner-card" href="https://www.roteskreuz.at/niederoesterreich/home" target="_blank" rel="noreferrer"><img alt="Red Cross Lower Austria" src="'+s+'" loading="lazy"></a><a class="partner-card" href="https://www.vbv.at/" target="_blank" rel="noreferrer"><img alt="VBV-Gruppe" src="'+o+'" loading="lazy"></a></div><div class="cta-row"><a class="md-button" href="/de/pentesting-demo-reports"><span class="iconify" data-icon="mdi:file-document" aria-hidden="true"></span> Zu unseren Demo-Berichten</a></div><h2 id="unsere-starken" tabindex="-1">Unsere Stärken <a class="header-anchor" href="#unsere-starken" aria-label="Permalink to &quot;Unsere Stärken&quot;">​</a></h2><h3 id="klarer-fokus" tabindex="-1">Klarer Fokus <a class="header-anchor" href="#klarer-fokus" aria-label="Permalink to &quot;Klarer Fokus&quot;">​</a></h3><p>Interne Infrastrukturen, Microsoft-Cloud und Web Security sind unsere Schwerpunkte. Mit diesem klaren Scope arbeiten wir fokussiert und effizient, damit Expertise und Aufwand dort ansetzen, wo sie für euch den größten Nutzen bringen.</p><h3 id="großtes-know-how" tabindex="-1">Größtes Know-how <a class="header-anchor" href="#großtes-know-how" aria-label="Permalink to &quot;Größtes Know-how&quot;">​</a></h3><p>Unser Team vereint Studium und Zertifizierungen in IT-Security mit langjähriger Pentest-Praxis. Dazu zählen Austausch in der europäischen Security-Community, Erfolge bei der European Cyber Security Challenge und internationale Übungen wie NATO Locked Shields.</p><h3 id="starkes-team" tabindex="-1">Starkes Team <a class="header-anchor" href="#starkes-team" aria-label="Permalink to &quot;Starkes Team&quot;">​</a></h3><p>Wir sind ein Team mit vielen Stärken und Erfahrungen in Industrie, Banken und Finanzen, öffentlichem Sektor, Universitäten, Gesundheitswesen, Handel und mehr. Aus unserer Pentest-Arbeit sind SysReptor für Pentest-Reporting und SysLeaks für Data-Leak-Monitoring entstanden, zwei international anerkannte Services.</p><h3 id="nachhaltige-kooperation" tabindex="-1">Nachhaltige Kooperation <a class="header-anchor" href="#nachhaltige-kooperation" aria-label="Permalink to &quot;Nachhaltige Kooperation&quot;">​</a></h3><p>Handschlagqualität, enger Austausch und persönlicher Kontakt sind für uns selbstverständlich und prägen unsere Zusammenarbeit mit euch. Wir wollen Security in eurer Organisation nachhaltig verbessern und setzen auf langfristige Partnerschaften.</p><br><div class="cta-row" style="text-align:center;"><a class="md-button" href="/de/contact-us" style="text-align:center;"><span class="iconify" data-icon="mdi:email-edit" aria-hidden="true"></span> Zu unseren Kontaktdaten</a></div><br>',19)])])}const w=l(h,[["render",m]]);export{S as __pageData,w as default};
